'use client';

import { motion } from 'framer-motion';

interface CrossExpandProps {
  width?: number;
  height?: number;
  color?: string;
  crossThickness?: number;
  cornerSize?: number;
  isAnimating?: boolean;
}

export function CrossExpand({
  width = 40,
  height = 40,
  color = "#25b09b",
  crossThickness = 8,
  cornerSize = 12,
  isAnimating = true,
}: CrossExpandProps) {
  const cx = width / 2;
  const cy = height / 2;

  // Corner square positions
  const cornerPositions = [
    { x: 0, y: 0 },
    { x: width - cornerSize, y: 0 },
    { x: 0, y: height - cornerSize },
    { x: width - cornerSize, y: height - cornerSize },
  ];

  // Expanded positions (move outward by ~10px)
  const expandOffset = width * 0.15;
  const expandedPositions = [
    { x: -expandOffset, y: -expandOffset },
    { x: width - cornerSize + expandOffset, y: -expandOffset },
    { x: -expandOffset, y: height - cornerSize + expandOffset },
    { x: width - cornerSize + expandOffset, y: height - cornerSize + expandOffset },
  ];

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Loading"
      role="img"
    >
      {/* Static center cross */}
      {/* Horizontal bar */}
      <rect
        x={0}
        y={cy - crossThickness / 2}
        width={width}
        height={crossThickness}
        fill={color}
        rx={crossThickness / 2}
      />
      {/* Vertical bar */}
      <rect
        x={cx - crossThickness / 2}
        y={0}
        width={crossThickness}
        height={height}
        fill={color}
        rx={crossThickness / 2}
      />
      {/* Animated corner squares */}
      {cornerPositions.map((pos, i) => (
        <motion.rect
          key={i}
          width={cornerSize}
          height={cornerSize}
          fill={color}
          rx={2}
          animate={{
            x: [pos.x, expandedPositions[i].x, expandedPositions[i].x, pos.x],
            y: [pos.y, expandedPositions[i].y, expandedPositions[i].y, pos.y],
            rotate: [0, 0, 90, 90],
          }}
          transition={{
            duration: 1.5,
            repeat: isAnimating ? Infinity : 0,
            times: [0, 0.33, 0.66, 1],
            ease: [0.3, 1, 0, 1],
          }}
          style={{ originX: `${pos.x + cornerSize / 2}px`, originY: `${pos.y + cornerSize / 2}px` }}
        />
      ))}
    </svg>
  );
}
